using UnityEngine;

namespace Sinnwrig.FogVolumes
{
    /// <summary>
    /// The primitive shape type to use when rendering a volume
    /// </summary>
    [System.Serializable]
    public enum VolumeType
    {
        Sphere = 0, 
        Cube = 1,
        Capsule = 2, 
        Cylinder = 3, 
    }


    internal static class VolumeTypeExtensions
    {
        // Material keywords generated by the [KeywordEnum] _Shape property of the fog shader
        internal static readonly string[] shapeKeywords = new string[]
        {
            "_SHAPE_SPHERE",
            "_SHAPE_CUBE",
            "_SHAPE_CAPSULE",
            "_SHAPE_CYLINDER"
        };


        /// <summary>
        /// The built-in mesh used to rasterize a volume of this type. 
        /// Built-in meshes are persistent assets, so they survive scene serialization and VRChat uploads.
        /// </summary>
        internal static Mesh GetProxyMesh(this VolumeType type)
        {
            // Spheres fit inside a unit cube. Capsules and cylinders are 1 unit wide and 2 units tall, same as the built-in cylinder.
            string meshName = type == VolumeType.Capsule || type == VolumeType.Cylinder ? "Cylinder.fbx" : "Cube.fbx";
            return Resources.GetBuiltinResource<Mesh>(meshName);
        }
    }
}
